    "author": "Efrem Sirul, Comentariu la Facere 2.6",
    "text": "Iar aceste patru râuri sunt, așadar, acestea: Pișonul, adică Dunărea; Ghihonul, adică Nilul; Tigrul și Eufratul. Între acestea locuim noi."
